function audit=auditV4ExperimentAFormalR5()
root=v4SetupPaths();base=fullfile(root,'results','formal','track_a','R5-point-anchored');loaded=load(fullfile(root,'results','reports','experiment_a_report_data.mat'),'report');report=loaded.report;methods=["No-Doppler" "Paper-Point" "Paper-Midamble-Point-native" "Stage55-point-anchored"];
complete=true;summaryMatch=true;pairedMatch=true;cellHashes=strings(20,1);seedRoots=zeros(20,1);total=0;
for caseIndex=1:2,for snrIndex=1:10,index=(caseIndex-1)*10+snrIndex;snrDb=-31+snrIndex;path=fullfile(base,'A-3S-param-v01',sprintf('case_%d',caseIndex),sprintf('snr_%+03d',snrDb),'formal_cell.mat');x=load(path,'formalCell');f=x.formalCell;state=f.state;cellHashes(index)=v4Sha256(path);seedRoots(index)=f.seedRoot;complete=complete&&f.completedPackets==20000&&f.fixedPackets==20000;total=total+f.completedPackets;
    for method=1:4,rows=report.summary.caseIndex==caseIndex&report.summary.snrDb==snrDb&report.summary.method==methods(method);rawErrors=sum(double(state.symbolErrors(:,method)));summaryMatch=summaryMatch&&sum(rows)==1&&report.summary.symbolErrors(rows)==rawErrors&&abs(report.summary.ser(rows)-rawErrors/(20000*23))<1e-15;end
    rows=report.pairedIntervals.caseIndex==caseIndex&report.pairedIntervals.snrDb==snrDb;rawDelta=mean((double(state.symbolErrors(:,4))-double(state.symbolErrors(:,3)))/23);pairedMatch=pairedMatch&&sum(rows)==1&&abs(report.pairedIntervals.stageMinusPaperDeltaSer(rows)-rawDelta)<1e-15&&report.pairedIntervals.bootstrapDraws(rows)==10000;
end,end
noBitMetrics=~report.reportsBitMetrics&&~any(contains(report.summary.Properties.VariableNames,{'ber','bit','per'},'IgnoreCase',true));source=v4VerifyReadOnlySources(root);passed=complete&&summaryMatch&&pairedMatch&&total==400000&&numel(unique(seedRoots))==20&&noBitMetrics&&source.passed;
audit=struct('stage','STAGE_04_EXPERIMENT_A_FORMAL_AUDIT','overall',status(passed),'fixedCells',20,'fixedPacketsPerCell',20000,'totalPairedPackets',total,'completeCells',status(complete),'rawToSummaryRecalculation',status(summaryMatch),'pairedDifferenceRecalculation',status(pairedMatch),'bootstrapDraws',10000,'seedRootsUnique',status(numel(unique(seedRoots))==20),'noPseudoBitMetrics',status(noBitMetrics),'sourceBoundary',status(source.passed),'cellHashes',cellHashes,'reportDataHash',v4Sha256(fullfile(root,'results','reports','experiment_a_report_data.mat')),'reportCodeHash',v4Sha256(fullfile(root,'scripts','buildV4ExperimentAReportR5.m')),'issuesAndFixes',{{'Initial report subtracted uint8 error counts before conversion, saturating negative paired differences. Report code was corrected to double(stage)-double(paper) and all derived report artifacts were rebuilt from unchanged formal cells and unchanged bootstrap seeds.'}},'admission',ternary(passed,'ADMIT_STAGE_5','DO_NOT_ADMIT_STAGE_5'));
folder=fullfile(root,'results','formal','track_a','R5-point-anchored');write(fullfile(folder,'STAGE_04_EXPERIMENT_A_FORMAL_AUDIT.json'),jsonencode(audit,'PrettyPrint',true));write(fullfile(folder,'STAGE_04_EXPERIMENT_A_FORMAL_AUDIT.md'),sprintf('# Stage 4 Experiment A formal audit\n\nOverall: `%s`; total paired packets: %d; admission: `%s`.\n\nRaw counts, SER and paired differences were independently recalculated. The uint8 report defect was corrected without changing formal cells.\n',audit.overall,total,audit.admission));if ~passed,error('V4:ExperimentAFormalAudit','Experiment A formal audit failed.');end
end
function x=status(ok),if ok,x='PASS';else,x='FAIL';end,end
function x=ternary(ok,a,b),if ok,x=a;else,x=b;end,end
function write(path,text),f=fopen(path,'w','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'%s\n',text);clear c,end
